#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back((int)e[1]);
        adj[e[1]].push_back((int)e[0]);
    }
    vector<int> tin(n + 1, 0), low(n + 1, 0), pos(n + 1, 0), parent(n + 1, 0);
    vector<char> cut(n + 1, 0);
    int timer = 0;
    for (int root = 1; root <= n; root++) {
        if (tin[root]) continue;
        timer++;
        tin[root] = low[root] = timer;
        int children = 0;
        vector<int> stack = {root};
        while (!stack.empty()) {
            int v = stack.back();
            if (pos[v] < (int)adj[v].size()) {
                int w = adj[v][pos[v]++];
                if (w == parent[v]) continue;
                if (tin[w]) {
                    low[v] = min(low[v], tin[w]);
                } else {
                    timer++;
                    tin[w] = low[w] = timer;
                    parent[w] = v;
                    stack.push_back(w);
                }
            } else {
                stack.pop_back();
                if (!stack.empty()) {
                    int p = stack.back();
                    low[p] = min(low[p], low[v]);
                    if (p != root && low[v] >= tin[p]) cut[p] = 1;
                    if (p == root) children++;
                }
            }
        }
        if (children >= 2) cut[root] = 1;
    }
    vector<int> found;
    for (int v = 1; v <= n; v++) {
        if (cut[v]) found.push_back(v);
    }
    cout << found.size() << "\n";
    for (size_t i = 0; i < found.size(); i++) cout << (i ? " " : "") << found[i];
    if (!found.empty()) cout << "\n";

    return 0;
}

