import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        int[] head = new int[nodes + 2];
        for (int i = 0; i < edges.length; i++) {
            head[(int) edges[i][0] + 1]++;
            head[(int) edges[i][1] + 1]++;
        }
        for (int v = 1; v <= nodes; v++) head[v + 1] += head[v];
        int[] to = new int[2 * edges.length];
        int[] eid = new int[2 * edges.length];
        int[] fill = new int[nodes + 2];
        for (int i = 0; i < edges.length; i++) {
            int a = (int) edges[i][0], b = (int) edges[i][1];
            to[head[a] + fill[a]] = b;
            eid[head[a] + fill[a]] = i;
            fill[a]++;
            to[head[b] + fill[b]] = a;
            eid[head[b] + fill[b]] = i;
            fill[b]++;
        }
        int[] tin = new int[nodes + 1], low = new int[nodes + 1], pos = new int[nodes + 1], parent = new int[nodes + 1];
        boolean[] cut = new boolean[nodes + 1];
        int[] stack = new int[nodes + 1];
        int timer = 0;
        for (int root = 1; root <= nodes; root++) {
            if (tin[root] != 0) continue;
            timer++;
            tin[root] = low[root] = timer;
            int children = 0;
            int top = 0;
            stack[top++] = root;
            while (top > 0) {
                int v = stack[top - 1];
                if (head[v] + pos[v] < head[v + 1]) {
                    int w = to[head[v] + pos[v]];
                    pos[v]++;
                    if (w == parent[v]) continue;
                    if (tin[w] != 0) {
                        low[v] = Math.min(low[v], tin[w]);
                    } else {
                        timer++;
                        tin[w] = low[w] = timer;
                        parent[w] = v;
                        stack[top++] = w;
                    }
                } else {
                    top--;
                    if (top > 0) {
                        int p = stack[top - 1];
                        low[p] = Math.min(low[p], low[v]);
                        if (p != root && low[v] >= tin[p]) cut[p] = true;
                        if (p == root) children++;
                    }
                }
            }
            if (children >= 2) cut[root] = true;
        }
        StringBuilder out = new StringBuilder();
        int count = 0;
        for (int v = 1; v <= nodes; v++) {
            if (cut[v]) {
                out.append(count > 0 ? " " : "").append(v);
                count++;
            }
        }
        System.out.println(count);
        if (count > 0) System.out.println(out);
    }
}
